from gurobipy import Model, GRB, quicksum
import sys

def FJSPModel(job_count, MacNum, OpNum, M_table, pt_table, M, X, Y, B):
    model = Model("FJSP_PPF")
    C_max = model.addVar(lb=0, ub=M, vtype="I", name="C_max")

    # Define variables
    # Define 0-1 decision variable Y[i,j,i',j']
    for i in range(job_count):
        for i_prime in range(job_count):
            for j in range(OpNum[i]):
                for j_prime in range(OpNum[i_prime]):
                    Y[i, j, i_prime, j_prime] = model.addVar(lb=0, ub=1, vtype="I", name=f"Y({i},{j},{i_prime},{j_prime})")

    # Define continuous decision variable B[i,j]
    for i in range(job_count):
        for j in range(OpNum[i]):
            B[i, j] = model.addVar(lb=0, vtype="C", name=f"B({i},{j})")

    # Define 0-1 decision variable X[i,j,k]
    for i in range(job_count):
        for j in range(OpNum[i]):
            for k in range(MacNum):
                X[i, j, k] = model.addVar(lb=0, ub=1, vtype="B", name=f"X({i},{j},{k})")

    # Objective function
    model.setObjective(C_max, GRB.MINIMIZE)

    # Constraint (1)
    for i in range(job_count):
        for j in range(OpNum[i]):
            model.addConstr(quicksum(X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) == 1, "assignment(%s,%s)" % (i, j))

    # Constraint (2)
    for i in range(job_count):
        for j in range(OpNum[i] - 1):
            model.addConstr(B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) <= B[i, j + 1], "predecessor(%s,%s)" % (i, j))

    # Constraint (3)
    for i in range(job_count):
        for i_prime in range(i + 1, job_count):
            for j in range(OpNum[i]):
                for j_prime in range(OpNum[i_prime]):
                    for k in range(MacNum):
                        if M_table[i][j][k] > 0 and M_table[i_prime][j_prime][k] > 0:
                            model.addConstr(B[i, j] + pt_table[i, j, k] * X[i, j, k] <= B[i_prime, j_prime] + M * (3 - Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]), "constraint3(%s,%s,%s,%s,%s)" % (i, j, i_prime, j_prime, k))

    # Constraint (3)
    for i in range(job_count):
        for i_prime in range(i + 1, job_count):
            for j in range(OpNum[i]):
                for j_prime in range(OpNum[i_prime]):
                    for k in range(MacNum):
                        if M_table[i][j][k] > 0 and M_table[i_prime][j_prime][k] > 0:
                            model.addConstr(B[i_prime, j_prime] + pt_table[i_prime, j_prime, k] * X[i_prime, j_prime, k] <= B[i, j] + M * (2 + Y[i, j, i_prime, j_prime] - X[i, j, k] - X[i_prime, j_prime, k]), "constraint4(%s,%s,%s,%s,%s)" % (i, j, i_prime, j_prime, k))

    # Constraint (4)
    for i in range(job_count):
        for j in range(OpNum[i]):
            model.addConstr(B[i, j] + quicksum(pt_table[i, j, k] * X[i, j, k] for k in range(MacNum) if M_table[i][j][k] > 0) <= C_max, "finish_time(%s,%s)" % (i, j))

    # Constraint (5)
    for i in range(job_count):
        for j in range(OpNum[i]):
            model.addConstr(B[i, j] >= 0, "non_negative_start_time(%s,%s)" % (i, j))

    # 约束6: 工件2的第2-3工序至少30间隔
    model.addConstr(B[1, 2] >= B[1, 1] + quicksum(pt_table[1, 1, k] * X[1, 1, k] for k in range(MacNum) if M_table[1][1][k] > 0) + 30, name="job2_op23_min_interval")


    # Set parameters
    model.params.TimeLimit = 10
    model.setParam('Threads', 20)
    model.update()

    return model

